// Every character listed as having relationship portraits has both extra ones (the base portrait is neutral), as 864 × 1152 PNGs [MM-story_mwpni0v4_3m]
// (was MM-task_mw9odkf0_4). The list is generated by tools/dialog/expression_prompts.py from the files present.
import test from 'node:test';
import assert from 'node:assert/strict';
import { existsSync, readFileSync } from 'node:fs';
import { MOOD_PORTRAITS } from './portraitMoods.js';

const pngSize = (buf) => (buf.subarray(0, 8).equals(Buffer.from([0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a])) ? [buf.readUInt32BE(16), buf.readUInt32BE(20)] : null);

test('each listed slug has its antagonistic and friendly portraits, 864 × 1152 PNG (neutral is the base)', () => {
  for (const slug of MOOD_PORTRAITS) for (const mood of ['antagonistic', 'friendly']) {
    const url = new URL(`../../content/dialog/portraits/${slug}-${mood}.png`, import.meta.url);
    assert.ok(existsSync(url), `${slug}-${mood}.png is missing`);
    assert.deepEqual(pngSize(readFileSync(url)), [864, 1152], `${slug}-${mood}.png must be an 864 × 1152 PNG`);
  }
});
